ation'=>'Tesis / disertasi','teaching_material'=>'Materi pembelajaran','other'=>'Lainnya'] as $key=>$label):?><option value="<?=$key;?>" <?=$v('contribution_type')===$key?'selected':'';?>><?=$label;?></option><?php endforeach;?></select></div><div class="col-md-6 mb-3"><label class="form-label">Penulis / Pencipta</label><input class="form-control" name="creator_names" value="<?=html_escape($v('creator_names'));?>"></div><div class="col-md-3 mb-3"><label class="form-label">Tahun</label><input type="number" min="1000" max="<?=date('Y')+1;?>" class="form-control" name="publication_year" value="<?=html_escape($v('publication_year'));?>"></div><div class="col-md-3 mb-3"><label class="form-label">Bahasa</label><input class="form-control" name="language" value="<?=html_escape($v('language'));?>" placeholder="Indonesia"></div></div><div class="mb-3"><label class="form-label">Deskripsi singkat</label><textarea class="form-control" name="description" rows="4" placeholder="Ringkasan isi, cakupan, dan alasan karya ini bermanfaat bagi masyarakat."><?=html_escape($v('description'));?></textarea></div><div class="section-title"><i class="ti ti-cloud-upload"></i>Berkas atau tautan</div><div class="row"><div class="col-md-6 mb-3"><label class="form-label">Unggah berkas</label><input class="form-control" type="file" name="donation_file" accept="application/pdf,application/epub+zip,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.oasis.opendocument.text,text/plain"><div class="form-hint">PDF, EPUB, DOC/DOCX, ODT, atau TXT; maksimal 200 MB.</div></div><div class="col-md-6 mb-3"><label class="form-label">Atau tautan berkas</label><input class="form-control" type="url" name="external_url" value="<?=html_escape($v('external_url'));?>" placeholder="https://drive.google.com/..."><div class="form-hint">Google Drive, OneDrive, repositori kampus, atau tautan HTTPS lain yang dapat ditinjau petugas.</div></div></div><div class="section-title"><i class="ti ti-license"></i>Hak cipta dan lisensi</div><div class="license-note mb-3"><strong>Hanya karya bebas hak cipta atau berlisensi terbuka yang diterima.</strong><br>Pilih lisensi yang benar. Petugas dapat meminta bukti tambahan atau menolak usulan yang status haknya tidak jelas.</div><div class="row"><div class="col-md-5 mb-3"><label class="form-label required">Lisensi</label><select required class="form-select" name="license_code"><option value="">Pilih lisensi bebas</option><option value="cc0" <?=$v('license_code')==='cc0'?'selected':'';?>>CC0 — pelepasan hak sejauh diizinkan hukum</option><option value="cc_by" <?=$v('license_code')==='cc_by'?'selected':'';?>>CC BY — boleh digunakan dengan atribusi</option><option value="cc_by_sa" <?=$v('license_code')==='cc_by_sa'?'selected':'';?>>CC BY-SA — atribusi dan berbagi serupa</option><option value="public_domain" <?=$v('license_code')==='public_domain'?'selected':'';?>>Domain publik</option></select></div><div class="col-md-7 mb-3"><label class="form-label">Keterangan hak / sumber lisensi</label><input class="form-control" name="rights_statement" value="<?=html_escape($v('rights_statement'));?>" placeholder="Contoh: Penulis adalah donor; dirilis CC BY 4.0 pada ..."></div></div><label class="form-check mb-3"><input required class="form-check-input" type="checkbox" name="rights_confirm" value="1" <?=!empty($old['rights_confirm'])?'checked':'';?>><span class="form-check-label">Saya menyatakan memiliki hak atau izin yang sah untuk menyerahkan karya ini dan menyetujui publikasi sesuai lisensi yang dipilih.</span></label><p class="privacy"><i class="ti ti-shield-check me-1"></i>Donasi tidak otomatis tayang. Data kontak hanya digunakan petugas untuk verifikasi dan tindak lanjut.</p><button class="btn btn-primary submit px-4" type="submit"><i class="ti ti-send me-1"></i>Kirim untuk Verifikasi</button><?=form_close();?></div></main><script>(function(){var form=document.getElementById('donation-form');if(!form)return;form.addEventListener('submit',function(e){var file=form.querySelector('[name="donation_file"]');if(file&&file.files[0]&&file.files[0].size>200*1024*1024){e.preventDefault();file.setCustomValidity('Ukuran berkas maksimal 200 MB.');file.reportValidity();file.setCustomValidity('');}})})();</script></body></html>
